/**
 * Unit tests for POJOPropertiesCollector._removeUnwantedAccessor
 */
public class POJOPropertiesCollector__removeUnwantedAccessor_TriageGen2Test {

    private MapperConfig<?> mockConfig;
    private POJOPropertiesCollector collector;

    @Before
    public void setUp() {
        mockConfig = mock(MapperConfig.class);
        // Using a subclass or spy because the constructor is protected
        // and we need to satisfy the constructor arguments.
        collector = new POJOPropertiesCollector(
                mockConfig, 
                true, 
                null, 
                null, 
                ""
        ) {
            // Since we are testing a protected method, we can call it via a wrapper 
            // or use reflection if it were private, but since it's protected 
            // and we are in the same package in the test, we can call it directly.
        };
    }

    /**
     * Helper class to expose the protected method for testing purposes if needed,
     * but since the test class is in the same package, we can call it directly.
     */
    private void callRemoveUnwantedAccessor(Map<String, POJOPropertyBuilder> props) {
        collector._removeUnwantedAccessor(props);
    }

    @Test
    public void testRemoveUnwantedAccessor_WithInferMutatorsEnabled() {
        // Arrange
        when(mockConfig.isEnabled(MapperFeature.INFER_PROPERTY_MUTATORS)).thenReturn(true);

        Map<String, POJOPropertyBuilder> props = new HashMap<>();
        POJOPropertyBuilder prop1 = mock(POJOPropertyBuilder.class);
        POJOPropertyBuilder prop2 = mock(POJOPropertyBuilder.class);
        props.put("prop1", prop1);
        props.put("prop2", prop2);

        // Act
        callRemoveUnwantedAccessor(props);

        // Assert
        verify(prop1, times(1)).removeNonVisible(true);
        verify(prop2, times(1)).removeNonVisible(true);
    }






}

